UPDATE ORDERS
SET ORDER_STATUS = 'EXCHANGE_REQUESTED'
WHERE ORDER_ID = #{orderId}
AND USER_ID = #{userId}

UPDATE product_stock
SET AVAILABLE_QTY = AVAILABLE_QTY - #{quantity}
WHERE OPTION_ITEM_ID = #{newOptionItemId}
AND AVAILABLE_QTY >= #{quantity}
ORDER BY STOCK_DATE DESC
LIMIT 1

UPDATE product_stock
SET AVAILABLE_QTY = AVAILABLE_QTY + #{quantity}
WHERE OPTION_ITEM_ID = #{oldOptionItemId}
ORDER BY STOCK_DATE DESC
LIMIT 1
